package nx.updater;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.util.*;import java.io.*;import java.security.*;
public final class GitHubReleases {
 private final DownloadManager http;public GitHubReleases(DownloadManager http){this.http=http;}
 public byte[] query(String url,Path cache,boolean force)throws Exception{Files.createDirectories(cache);Path body=cache.resolve("releases.json"),meta=cache.resolve("http.properties");Properties p=new Properties();if(Files.exists(meta))try(InputStream in=Files.newInputStream(meta)){p.load(in);}if(!url.equals(p.getProperty("sourceUrl",""))){p.clear();Files.deleteIfExists(body);}if(!force&&Files.exists(body)&&System.currentTimeMillis()-Files.getLastModifiedTime(body).toMillis()<600000)return Files.readAllBytes(body);
  Map<String,String> headers=new HashMap<>();headers.put("Accept","application/vnd.github+json");headers.put("X-GitHub-Api-Version","2022-11-28");if(p.containsKey("etag"))headers.put("If-None-Match",p.getProperty("etag"));HttpURLConnection c=http.connect(url,headers);
  try{if(c.getResponseCode()==304&&Files.exists(body))return Files.readAllBytes(body);if(c.getResponseCode()!=200)throw new IOException(c.getResponseCode()==404?"Repositorio sin acceso público o inexistente; revisa distribución": "GitHub HTTP "+c.getResponseCode()+"; intenta más tarde");byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] a=new byte[8192];int n;while((n=in.read(a))>=0){if(b.size()+n>4*1024*1024)throw new IOException("Catálogo excesivo");b.write(a,0,n);}bytes=b.toByteArray();}Json.array(Json.parse(new String(bytes,StandardCharsets.UTF_8)));Files.write(body,bytes);String et=c.getHeaderField("ETag");p.setProperty("sourceUrl",url);if(et!=null){p.setProperty("etag",et);try(OutputStream out=Files.newOutputStream(meta)){p.store(out,"NX Updater HTTP cache");}}return bytes;}finally{c.disconnect();}}
 public static final class Offer {public final UpdateManifest manifest;public final byte[] raw,signature;public final String releaseUrl;Offer(UpdateManifest m,byte[] raw,byte[] sig,String link){manifest=m;this.raw=raw;signature=sig;releaseUrl=link;}}
 public Offer select(byte[] catalog,String platform,String channel,String installed,String protocol,PublicKey trusted)throws Exception{Offer best=null;for(Object r:Json.array(Json.parse(new String(catalog,StandardCharsets.UTF_8)))){Map<String,Object> release=Json.object(r);if(Boolean.TRUE.equals(release.get("draft")))continue;if(channel.equals("STABLE")&&Boolean.TRUE.equals(release.get("prerelease")))continue;String manifest=null,sig=null;String assetName="NX_UPDATE_"+platform+"_"+channel.replace(' ','_')+".json";for(Object a:Json.array(release.get("assets"))){Map<String,Object> asset=Json.object(a);String name=Json.str(asset,"name");if(name.equals(assetName))manifest=Json.str(asset,"browser_download_url");if(name.equals(assetName+".sig"))sig=Json.str(asset,"browser_download_url");}if(manifest==null||sig==null)continue;
   byte[] raw=http.bytes(manifest,4*1024*1024),signature=http.bytes(sig,16384);UpdateManifest m=UpdateManifest.verified(raw,signature,trusted);
   if(!Arrays.asList("DEVELOPMENT","RELEASE CANDIDATE","STABLE").contains(m.channel)||!m.platform.equals(platform)||!m.channel.equals(channel)||new SemVer(m.version).compareTo(new SemVer(installed))<=0)continue;
   m.compatible(installed,platform,channel,protocol);for(UpdateManifest.Entry e:m.files)if(!e.action.equals("DELETE"))http.validate(e.url);
   if(best==null||new SemVer(m.version).compareTo(new SemVer(best.manifest.version))>0)best=new Offer(m,raw,signature,String.valueOf(release.getOrDefault("html_url","")));
  }return best;}
}
